+import { addTrait, getTrait, hasTrait, removeTrait, setTrait } from '../trait/trait';
+import type { Trait, TraitRecord } from '../trait/types';
+import type { World } from '../world';
+import { $aspect } from './symbols';
+import type { Aspect, AspectRecord } from './types';
+
+let aspectId = 0;
+
+export function isAspect(value: unknown): value is Aspect {
+    return !!(value as Aspect | undefined)?.[$aspect];
+}
+
+export function createAspect<T extends [Trait, Trait, ...Trait[]]>(...inputs: T): Aspect<T> {
+    const traits: Trait[] = [];
+    for (const input of inputs) {
+        if (isAspect(input)) traits.push(...input.traits);
+        else traits.push(input);
+    }
+
+    const fields = new Set<string>();
+    const schema: Record<string, unknown> = {};
+    for (const trait of traits) {
+        if (trait[$internal].relation) throw new Error('Aspects cannot contain relation traits.');
+        for (const field of Object.keys(trait.schema as Schema)) {
+            if (fields.has(field)) throw new Error(`Aspect traits cannot share the field "${field}".`);
+            fields.add(field);
+            schema[field] = (trait.schema as Record<string, unknown>)[field];
+        }
+    }
+
+    return Object.freeze({ [$aspect]: true as const, id: aspectId++, traits: Object.freeze(traits), schema }) as Aspect<T>;
+}
+
+export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
+    return aspect.traits.every((trait) => hasTrait(world, entity, trait));
+}
+
+export function getAspect(world: World, entity: Entity, aspect: Aspect): AspectRecord<Aspect> | undefined {
+    if (!hasAspect(world, entity, aspect)) return undefined;
+    const result: Record<string, unknown> = {};
+    for (const trait of aspect.traits) Object.assign(result, getTrait(world, entity, trait));
+    return result;
+}
+
+export function setAspect(world: World, entity: Entity, aspect: Aspect, value: any, changed = true) {
+    for (const trait of aspect.traits) {
+        const part = pickFields(trait, value);
+        if (Object.keys(part).length) setTrait(world, entity, trait, part, changed);
+    }
+}
+
+export function addAspect(world: World, entity: Entity, aspect: Aspect, value: any = {}) {
+    for (const trait of aspect.traits) {
+        if (!hasTrait(world, entity, trait)) addTrait(world, entity, [trait, pickFields(trait, value)]);
+    }
+}
+
+export function removeAspect(world: World, entity: Entity, aspect: Aspect) {
+    removeTrait(world, entity, ...aspect.traits);
+}
+
+export function pickFields(trait: Trait, value: Record<string, unknown>): Record<string, unknown> {
+    const result: Record<string, unknown> = {};
+    for (const field of Object.keys(trait.schema)) {
+        if (field in value) result[field] = value[field];
+    }
+    return result;
+}
