+function createAspectQueryResult(world: World, entities: Entity[], query: QueryInstance, params: QueryParameter[]) {
+    const results = Object.assign(entities, {
+        readEach(callback: any) {
+            for (let i = 0; i < entities.length; i++) callback(readAspectState(world, entities[i], params), entities[i], i);
+            return results;
+        },
+        updateEach(callback: any, options: QueryResultOptions = { changeDetection: 'auto' }) {
+            for (let i = 0; i < entities.length; i++) {
+                const entity = entities[i];
+                const state = readAspectState(world, entity, params);
+                callback(state, entity, i);
+                if (!world.has(entity)) continue;
+                for (let j = 0; j < params.length; j++) {
+                    const param = params[j];
+                    if (!isAspect(param)) continue;
+                    for (const trait of param.traits) {
+                        const before = getTraitValue(world, entity, trait);
+                        const value = pickFields(trait, state[j]);
+                        if (options.changeDetection === 'never') trait[$internal].fastSet(entity.id(), getStore(world, trait), value);
+                        else if (trait[$internal].fastSetWithChangeDetection(entity.id(), getStore(world, trait), value)) setChanged(world, entity, trait);
